1	// This file adds snapshot-based source tracing: given one validated snapshot
2	// and a dataset name, it reports every root source reachable from that
3	// dataset through direct upstream edges, together with one shortest path per
4	// root. The answer depends only on the snapshot's graph semantics, so a later
5	// change to the live graph never alters what a frozen version reports.
6	package chainledger
7	
8	import (
9		"fmt"
10		"sort"
11	)
12	
13	// SourceTrace links one reachable root source to the path that reaches it.
14	//
15	// Path starts at the queried dataset and ends at Root, listing every dataset
16	// name along the way, both endpoints included. When the queried dataset is
17	// itself a root, Path is the single-element array holding its own name.
18	type SourceTrace struct {
19		Root string   `json:"root"`
20		Path []string `json:"path"`
21	}
22	
23	// TraceReport is the deterministic, read-only answer of a source trace
24	// against one snapshot.
25	//
26	// ContentID is the snapshot's own content identifier, Dataset is the queried
27	// name exactly as given, and Sources lists every reachable root once, sorted
28	// by root name byte order.
29	type TraceReport struct {
30		ContentID string        `json:"contentId"`
31		Dataset   string        `json:"dataset"`
32		Sources   []SourceTrace `json:"sources"`
33	}
34	
35	// TraceSources traces the root sources of dataset within the graph frozen in
36	// snap. The snapshot is assumed to have passed ParseSnapshot; it is only read,
37	// never modified.
38	//
39	// Every reachable root is reported exactly once with one shortest path (fewest
40	// direct relations). Among equally short paths the one chosen is the smallest
41	// when the names are compared element by element from the start of the path in
42	// UTF-8 byte order. Roots sharing intermediate datasets keep their own paths.
43	//
44	// An empty dataset name or a name absent from the snapshot is an error.
45	func TraceSources(snap *SnapshotFile, dataset string) (*TraceReport, error) {
46		if dataset == "" {
47			return nil, fmt.Errorf("%w: dataset name to trace must not be empty", ErrInvalidArgument)
48		}
49		adj := adjacencyFromValidFile(snap.Graph)
50		if _, ok := adj[dataset]; !ok {
51			return nil, fmt.Errorf("%w: dataset %q is not in the snapshot", ErrNotFound, dataset)
52		}
53	
54		// Breadth-first walk from the queried dataset along direct upstream
55		// edges. best[node] holds the shortest, tie-broken path from the query to
56		// node; because every edge has the same weight, the first level at which
57		// a node is reached is its shortest distance, and keeping only the
58		// smallest candidate path per node preserves the global minimum.
59		best := map[string][]string{dataset: {dataset}}
60		frontier := []string{dataset}
61		for len(frontier) > 0 {
62			candidates := make(map[string][]string)
63			for _, node := range frontier {
64				for _, parent := range adj[node] {
65					if _, seen := best[parent]; seen {
66						continue
67					}
68					path := append(append([]string{}, best[node]...), parent)
69					if current, ok := candidates[parent]; !ok || pathLess(path, current) {
70						candidates[parent] = path
71					}
72				}
73			}
74			next := make([]string, 0, len(candidates))
75			for node, path := range candidates {
76				best[node] = path
77				next = append(next, node)
78			}
79			frontier = next
80		}
81	
82		sources := make([]SourceTrace, 0)
83		for node, path := range best {
84			if len(adj[node]) == 0 {
85				sources = append(sources, SourceTrace{Root: node, Path: path})
86			}
87		}
88		sort.Slice(sources, func(i, j int) bool { return sources[i].Root < sources[j].Root })
89	
90		return &TraceReport{
91			ContentID: snap.ContentID,
92			Dataset:   dataset,
93			Sources:   sources,
94		}, nil
95	}
96	
97	// pathLess compares two equal-purpose paths element by element from the start
98	// using plain string (UTF-8 byte) order, deciding on the first differing
99	// name. A strict prefix counts as smaller, matching lexicographic order.
100	func pathLess(a, b []string) bool {
101		for i := 0; i < len(a) && i < len(b); i++ {
102			if a[i] != b[i] {
103				return a[i] < b[i]
104			}
105		}
106		return len(a) < len(b)
107	}
108

