36	// branchOldGraph is the multi-root convergence fixture: three roots, two
37	// branches to rootA (a1 directly, a0 via a short chain) where a2 also carries
38	// rootC, one branch to rootB (b1), a merge node where every branch converges,
39	// and TWO levels of datasets derived after the merge (down, down2). "solo" is
40	// an unrelated disconnected root that no trace from the converging component
41	// may ever report.
42	const branchOldGraph = `{"datasets":[
43		{"name":"rootA","upstreams":[]},
44		{"name":"rootB","upstreams":[]},
45		{"name":"rootC","upstreams":[]},
46		{"name":"a0","upstreams":["rootA"]},
47		{"name":"a1","upstreams":["rootA"]},
48		{"name":"a2","upstreams":["rootA","rootC"]},
49		{"name":"b1","upstreams":["rootB"]},
50		{"name":"merge","upstreams":["a1","a2","b1"]},
51		{"name":"down","upstreams":["merge"]},
52		{"name":"down2","upstreams":["down"]},
53		{"name":"solo","upstreams":[]}
54	]}`
