71	// traceRoots runs a source trace and returns just the sorted root names,
72	// failing the test if the trace does not succeed.
73	func traceRoots(t *testing.T, snap *SnapshotFile, dataset string) []string {
74		t.Helper()
75		report, err := TraceSources(snap, dataset)
76		if err != nil {
77			t.Fatalf("TraceSources(%q): %v", dataset, err)
78		}
79		roots := make([]string, 0, len(report.Sources))
80		for _, src := range report.Sources {
81			roots = append(roots, src.Root)
82		}
83		return roots
84	}
