138	// assertTraceAgreesWithCompare is the headline invariant of this file: for
139	// every common dataset the roots TraceSources reports in each version equal
140	// the compare report's oldRoots/newRoots, the dataset appears in
141	// rootSourceChanges exactly when the two traced sets differ, and every traced
142	// path is a real edge-walk that ends at a genuine root. Datasets present on
143	// only one side are never looked up here (the caller pins their trace
144	// failure separately).
145	func assertTraceAgreesWithCompare(t *testing.T, oldSnap, newSnap *SnapshotFile, report *CompareReport) {
146		t.Helper()
147		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
148		newAdj := adjacencyFromValidFile(newSnap.Graph)
149		changes := rootChangeMap(report)
150		for _, name := range commonNamesIn(oldSnap, newSnap) {
151			oldReport, err := TraceSources(oldSnap, name)
152			if err != nil {
153				t.Fatalf("old TraceSources(%q): %v", name, err)
154			}
155			newReport, err := TraceSources(newSnap, name)
156			if err != nil {
157				t.Fatalf("new TraceSources(%q): %v", name, err)
158			}
159			assertTracePathsAreReal(t, oldReport, oldAdj)
160			assertTracePathsAreReal(t, newReport, newAdj)
161			oldTraced := traceRoots(t, oldSnap, name)
162			newTraced := traceRoots(t, newSnap, name)
163	
164			change, listed := changes[name]
165			setsDiffer := !reflect.DeepEqual(oldTraced, newTraced)
166			if listed != setsDiffer {
167				t.Errorf("dataset %q: trace root sets differ=%v but rootSourceChanges lists it=%v (old=%v new=%v)",
168					name, setsDiffer, listed, oldTraced, newTraced)
169			}
170			if listed {
171				if !reflect.DeepEqual(change.OldRoots, oldTraced) {
172					t.Errorf("dataset %q oldRoots = %v, want old trace roots %v", name, change.OldRoots, oldTraced)
173				}
174				if !reflect.DeepEqual(change.NewRoots, newTraced) {
175					t.Errorf("dataset %q newRoots = %v, want new trace roots %v", name, change.NewRoots, newTraced)
176				}
177			}
178		}
179		// The converse: every name the report lists really is common to both.
180		for _, change := range report.RootSourceChanges {
181			if _, ok := oldAdj[change.Dataset]; !ok {
182				t.Errorf("rootSourceChanges lists %q, absent from the old snapshot", change.Dataset)
183			}
184			if _, ok := newAdj[change.Dataset]; !ok {
185				t.Errorf("rootSourceChanges lists %q, absent from the new snapshot", change.Dataset)
186			}
187		}
188	}
