30	//     graph object, name or upstreams in a dataset record) is rejected,
31	//     however the two declarations are spelled; that JSON-level scan is
32	//     shared by every document reader and lives in duplicate_fields.go.
33	//
34	// The snapshot-only envelope rules (required fields, format version, content
35	// identifier, and duplicates of the snapshot's own fields) live in
36	// snapshot.go; this file is only the common graph structure.
37	package chainledger
38	
39	import (
40		"fmt"
41		"sort"
42		"strings"
43		"unicode/utf8"
44	)
45	
46	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
47	type adjacency map[string][]string
48	
49	// validateInMemoryNamesUTF8 rejects an in-memory graph whose dataset name or
50	// direct upstream reference is not valid UTF-8.
51	//
52	// Such names cannot exist in a file read by the JSON readers (json.Unmarshal
53	// replaces invalid bytes with U+FFFD), but they can exist in a graph built
54	// through Register or by hand. They must never reach an exporter: encoding/json
55	// would silently replace every invalid byte with U+FFFD, so two different
56	// names ("p\xff" and "p\xfe") could serialize identically and a re-read graph
57	// would no longer be a faithful copy. The whole graph is rejected instead.
58	//
59	// Nodes are visited in name byte order and each node's parents in their stored
60	// order, so the first reported name is stable regardless of map iteration.
61	// The offending name is quoted with %q, which keeps the raw bytes readable
62	// ("p\xff" differs from "p\xfe", and a genuinely valid "p�" is shown as
63	// the replacement character itself). The graph is only read, never modified.
64	// Nil lineage nodes are skipped here; the caller rejects those separately.
65	func validateInMemoryNamesUTF8(graph map[string]*Lineage) error {
66		names := make([]string, 0, len(graph))
67		for name := range graph {
68			names = append(names, name)
69		}
70		sort.Strings(names)
71		for _, name := range names {
72			if !utf8.ValidString(name) {
73				return fmt.Errorf("%w: dataset name %q is not valid UTF-8, so the graph cannot be exported faithfully", ErrInvalidArgument, name)
74			}
75			entry := graph[name]
76			if entry == nil {
77				continue
78			}
79			for _, parent := range entry.Parents {
80				if !utf8.ValidString(parent) {
81					return fmt.Errorf("%w: dataset %q references upstream %q whose name is not valid UTF-8", ErrInvalidArgument, name, parent)
82				}
83			}
84		}
85		return nil
86	}
