88	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
89	// records. It rejects empty dataset names and datasets declared more than
90	// once; every surviving upstream list is sorted and deduplicated. It does not
91	// check that upstreams resolve to a declared dataset; use
92	// firstMissingReference for that.
93	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
94		adj := make(adjacency, len(datasets))
95		for _, ds := range datasets {
96			if ds.Name == "" {
97				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
98			}
99			if _, exists := adj[ds.Name]; exists {
100				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
101			}
102			adj[ds.Name] = uniqueSorted(ds.Upstreams)
103		}
104		return adj, nil
105	}
106	
107	// firstMissingReference is the single authority for the direct-upstream rule,
108	// shared by every graph that gets checked: the graph read from a file, the
109	// graph embedded in a snapshot, a live in-memory graph, and the final graph a
110	// batch converges on. Every direct upstream a dataset names must be a dataset
111	// that exists in the graph being checked; nothing else is judged here (the
112	// cycle rule lives in validateAcyclic).
113	//
114	// Referrers are visited in sorted name byte order and each referrer's parents
115	// in sorted byte order, so the first reported (referrer, upstream) pair is
116	// stable regardless of map iteration, record order, or upstream input order.
117	// Names are compared verbatim — case and surrounding whitespace matter — and
118	// a parent list is expected to already be normalized, so a repeated upstream
119	// is one relationship and can only be reported once. An empty graph or a
120	// dataset with no parents yields ok == false.
121	func firstMissingReference(adj adjacency) (referrer, referenced string, ok bool) {
122		names := make([]string, 0, len(adj))
123		for name := range adj {
124			names = append(names, name)
125		}
126		sort.Strings(names)
127		for _, name := range names {
128			for _, parent := range adj[name] {
129				if _, exists := adj[parent]; !exists {
130					return name, parent, true
131				}
132			}
133		}
134		return "", "", false
135	}
