3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"reflect"
8		"testing"
9	)
10	
11	// This file is the regression net for the independence of source-trace reports
12	// returned by TraceSources. A caller that receives a *TraceReport keeps editing
13	// it for display, may hold several reports of the same snapshot at once (and
14	// reports for other datasets that pass through the same shared intermediate),
15	// and keeps holding the input snapshot. None of those views may alias each
16	// other or the snapshot:
17	//
18	//   - editing one source record (its root name, or a name at any position of
19	//     its path, or appending a name to that path) changes only that record,
20	//     even when two paths share a prefix (T -> M -> R1 and T -> M -> R2 both
21	//     start with T, M) — the other record keeps its own root and full path;
22	//   - reordering or removing entries of the sources array never reaches the
23	//     input snapshot's dataset names or direct upstream relations;
24	//   - editing one returned report leaves every other returned report (for the
25	//     same query or for another downstream through the same intermediate)
26	//     representing the result at the moment it was obtained, and a fresh query
27	//     after the edits still reports the frozen snapshot's sources and paths;
28	//   - the snapshot itself keeps the same content identifier, graph, and export
29	//     bytes before and after tracing, including after failed queries;
30	//   - a single-element path for a root query has the same independence;
31	//   - a failed query (empty name or unknown name) keeps using the existing
32	//     error categories, returns no success report, and changes neither an
33	//     earlier report nor the snapshot;
34	//   - every independent result still obeys the existing business rules: each
35	//     root once, fewest direct relations first, equal-length ties decided
36	//     element by element from the query end in UTF-8 byte order, sources sorted
37	//     by root name, and Chinese/case/space spellings preserved verbatim.
38	
39	// traceIndependenceGraphJSON is the shared-prefix fixture: the derived
40	// datasets T and U both reach the two roots R1 and R2 through the common
41	// intermediate M, so T's two reported paths [T M R1] and [T M R2] share the
42	// prefix [T M]. X is a disconnected root and must never be reported.
43	const traceIndependenceGraphJSON = `{"datasets":[
44		{"name":"T","upstreams":["M"]},
45		{"name":"U","upstreams":["M"]},
46		{"name":"M","upstreams":["R1","R2"]},
47		{"name":"R1","upstreams":[]},
48		{"name":"R2","upstreams":[]},
49		{"name":"X","upstreams":[]}
50	]}`
51	
52	// wantIndependenceTSources is the exact source report for T, sources sorted by
53	// root name byte order with complete query-to-root paths.
54	var wantIndependenceTSources = []SourceTrace{
55		{Root: "R1", Path: []string{"T", "M", "R1"}},
56		{Root: "R2", Path: []string{"T", "M", "R2"}},
57	}
58	
59	// wantIndependenceUSources is the report for the other downstream through the
60	// same shared intermediate.
61	var wantIndependenceUSources = []SourceTrace{
62		{Root: "R1", Path: []string{"U", "M", "R1"}},
63		{Root: "R2", Path: []string{"U", "M", "R2"}},
64	}
65	
66	// wantIndependenceSnapshotDatasets is the frozen graph as the snapshot stores
67	// it: records sorted by name, roots with a non-nil empty upstream list.
68	var wantIndependenceSnapshotDatasets = []GraphDataset{
69		{Name: "M", Upstreams: []string{"R1", "R2"}},
70		{Name: "R1", Upstreams: []string{}},
71		{Name: "R2", Upstreams: []string{}},
72		{Name: "T", Upstreams: []string{"M"}},
73		{Name: "U", Upstreams: []string{"M"}},
74		{Name: "X", Upstreams: []string{}},
75	}
76	
77	// traceReportOf traces dataset in snap, failing the test on error.
78	func traceReportOf(t *testing.T, snap *SnapshotFile, dataset string) *TraceReport {
79		t.Helper()
80		report, err := TraceSources(snap, dataset)
81		if err != nil {
82			t.Fatalf("TraceSources(%q): %v", dataset, err)
83		}
84		return report
85	}
86	
87	// mustMarshalTraceReport renders a report the way a caller displaying it would.
88	func mustMarshalTraceReport(t *testing.T, report *TraceReport) []byte {
89		t.Helper()
90		data, err := json.Marshal(report)
91		if err != nil {
92			t.Fatalf("json.Marshal report unexpected error: %v", err)
93		}
94		return data
95	}
96	
97	// snapshotDatasetsCopy deep-copies the snapshot's dataset records so a test can
98	// compare names and direct upstreams after the caller mutates a returned
99	// report. Empty upstream lists stay non-nil, matching the snapshot's own
100	// representation.
101	func snapshotDatasetsCopy(snap *SnapshotFile) []GraphDataset {
102		datasets := make([]GraphDataset, len(snap.Graph.Datasets))
103		for i, ds := range snap.Graph.Datasets {
104			upstreams := make([]string, len(ds.Upstreams))
105			copy(upstreams, ds.Upstreams)
106			datasets[i] = GraphDataset{Name: ds.Name, Upstreams: upstreams}
107		}
108		return datasets
109	}
110	
111	// sourceForRoot finds the record for root in report, so tests can locate the
112	// "other" record after the sources array has been reordered.
113	func sourceForRoot(report *TraceReport, root string) (SourceTrace, bool) {
114		for _, src := range report.Sources {
115			if src.Root == root {
116				return src, true
117			}
118		}
119		return SourceTrace{}, false
120	}
121	
122	// TestTraceEditingOneSharedPrefixPathLeavesTheOtherUntouched is the headline
123	// aliasing guarantee: every edit a caller can make inside one source record of
124	// a two-path report must change only that record. The other record keeps its
125	// original root and its complete path, including the shared T, M prefix; the
126	// report-level identifiers and the input snapshot stay exactly as returned.
127	func TestTraceEditingOneSharedPrefixPathLeavesTheOtherUntouched(t *testing.T) {
128		edits := map[string]func(*TraceReport, int){
129			"replace query name in path": func(r *TraceReport, i int) {
130				r.Sources[i].Path[0] = "HACK"
131			},
132			"replace intermediate name in path": func(r *TraceReport, i int) {
133				r.Sources[i].Path[1] = "HACK"
134			},
135			"replace root name in path": func(r *TraceReport, i int) {
136				r.Sources[i].Path[2] = "HACK"
137			},
138			"append name to path": func(r *TraceReport, i int) {
139				r.Sources[i].Path = append(r.Sources[i].Path, "EXTRA")
140			},
141			"replace root field": func(r *TraceReport, i int) {
142				r.Sources[i].Root = "HACK"
143			},
144		}
145		// Sources are sorted by root name, so R1 is first and R2 second; exercise
146		// the edit in both directions, since either shared-prefix path could alias.
147		targets := []struct {
148			editedIndex int
149			editedRoot  string
150			otherRoot   string
151			other       SourceTrace
152		}{
153			{0, "R1", "R2", SourceTrace{Root: "R2", Path: []string{"T", "M", "R2"}}},
154			{1, "R2", "R1", SourceTrace{Root: "R1", Path: []string{"T", "M", "R1"}}},
155		}
156		for _, target := range targets {
157			for editName, edit := range edits {
158				t.Run(target.editedRoot+"/"+editName, func(t *testing.T) {
159					snap := snapshotOf(t, traceIndependenceGraphJSON)
160					report := traceReportOf(t, snap, "T")
161	
162					edit(report, target.editedIndex)
163	
164					// The other record is byte-for-byte the original: its root, and
165					// every name of its full path, including the shared prefix.
166					got, ok := sourceForRoot(report, target.otherRoot)
167					if !ok {
168						t.Fatalf("other source %q vanished after editing %q", target.otherRoot, target.editedRoot)
169					}
170					if !reflect.DeepEqual(got, target.other) {
171						t.Errorf("other source = %+v, want untouched %+v", got, target.other)
172					}
173	
174					// The edit really landed on the record the caller changed.
175					if edited, ok := sourceForRoot(report, target.editedRoot); ok && reflect.DeepEqual(edited, target.other) {
176						t.Errorf("editing %q had no local effect: %+v", target.editedRoot, edited)
177					}
178	
179					// Report-level identifiers are separate fields from the paths:
180					// rewriting a path's query name never moves Dataset.
181					if report.Dataset != "T" {
182						t.Errorf("report Dataset = %q, want %q", report.Dataset, "T")
183					}
184					if report.ContentID != snap.ContentID {
185						t.Errorf("report ContentID = %q, want %q", report.ContentID, snap.ContentID)
186					}
187	
188					// The input snapshot keeps every dataset name and direct
189					// upstream relation.
190					if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, wantIndependenceSnapshotDatasets) {
191						t.Errorf("snapshot changed after editing a report record:\n got %v\nwant %v", got, wantIndependenceSnapshotDatasets)
192					}
193				})
194			}
195		}
196	}
197	
198	// TestTraceReorderingAndRemovingSourcesLeavesSnapshotAndRequeryUntouched pins
199	// the array-level edits: swapping the two source records, mutating a path after
200	// the swap, and dropping a record from the array must not move the snapshot,
201	// and a fresh query still reports both roots with their full original paths.
202	func TestTraceReorderingAndRemovingSourcesLeavesSnapshotAndRequeryUntouched(t *testing.T) {
203		snap := snapshotOf(t, traceIndependenceGraphJSON)
204		wantID := snap.ContentID
205		snapshotBytes := mustMarshalSnapshot(t, snap)
206	
207		report := traceReportOf(t, snap, "T")
208		report.Sources[0], report.Sources[1] = report.Sources[1], report.Sources[0]
209	
210		// After the swap each record still owns its own complete path.
211		if got, ok := sourceForRoot(report, "R1"); !ok || !reflect.DeepEqual(got, wantIndependenceTSources[0]) {
212			t.Errorf("R1 after swap = %+v ok=%v, want %+v", got, ok, wantIndependenceTSources[0])
213		}
214		if got, ok := sourceForRoot(report, "R2"); !ok || !reflect.DeepEqual(got, wantIndependenceTSources[1]) {
215			t.Errorf("R2 after swap = %+v ok=%v, want %+v", got, ok, wantIndependenceTSources[1])
216		}
217		// Mutating through the swapped position edits the record now held there
218		// (R2's), never R1's record.
219		report.Sources[0].Path[0] = "HACK"
220		if got, ok := sourceForRoot(report, "R1"); !ok || !reflect.DeepEqual(got, wantIndependenceTSources[0]) {
221			t.Errorf("R1 changed after editing the swapped R2 record: %+v ok=%v", got, ok)
222		}
223	
224		// A separate report from which the caller removes one record.
225		pruned := traceReportOf(t, snap, "T")
226		pruned.Sources = pruned.Sources[:1]
227		if len(pruned.Sources) != 1 || pruned.Sources[0].Root != "R1" {
228			t.Fatalf("pruned report = %+v, want only R1", pruned.Sources)
229		}
230	
231		// The snapshot is unchanged: content id, graph, export bytes.
232		if snap.ContentID != wantID {
233			t.Errorf("content id changed: %q", snap.ContentID)
234		}
235		if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, wantIndependenceSnapshotDatasets) {
236			t.Errorf("snapshot changed:\n got %v\nwant %v", got, wantIndependenceSnapshotDatasets)
237		}
238		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, snapshotBytes) {
239			t.Errorf("snapshot export changed:\n got %s\nwant %s", got, snapshotBytes)
240		}
241	
242		// A fresh query still sees both roots and both full paths.
243		fresh := traceReportOf(t, snap, "T")
244		if !reflect.DeepEqual(fresh.Sources, wantIndependenceTSources) {
245			t.Errorf("fresh query after edits = %+v, want %+v", fresh.Sources, wantIndependenceTSources)
246		}
247		if fresh.ContentID != snap.ContentID || fresh.Dataset != "T" {
248			t.Errorf("fresh report metadata = %q %q, want %q %q", fresh.ContentID, fresh.Dataset, snap.ContentID, "T")
249		}
250	}
251	
252	// TestTraceReturnedReportsAreIndependentOfEachOther verifies that with several
253	// reports held at once — two of the same query and one of another downstream
254	// through the same shared intermediate — thoroughly editing one report leaves
255	// the others representing their return-time results, the snapshot frozen, and
256	// fresh queries of T and U reporting the original sources and paths.
257	func TestTraceReturnedReportsAreIndependentOfEachOther(t *testing.T) {
258		snap := snapshotOf(t, traceIndependenceGraphJSON)
259		first := traceReportOf(t, snap, "T")
260		second := traceReportOf(t, snap, "T")
261		downU := traceReportOf(t, snap, "U")
262	
263		wantSecond := mustMarshalTraceReport(t, second)
264		wantU := mustMarshalTraceReport(t, downU)
265		snapshotBytes := mustMarshalSnapshot(t, snap)
266	
267		// Edit the first report as thoroughly as a caller might: report-level
268		// identifiers, both root fields, every path position, appends into both
269		// paths (including the shared prefix), and a fabricated extra source.
270		first.ContentID = "HACK"
271		first.Dataset = "HACK"
272		first.Sources[0].Root = "HACK"
273		first.Sources[0].Path[0] = "HACK"
274		first.Sources[0].Path[1] = "HACK"
275		first.Sources[0].Path[2] = "HACK"
276		first.Sources[0].Path = append(first.Sources[0].Path, "EXTRA")
277		first.Sources[1].Path = append(first.Sources[1].Path, "EXTRA")
278		first.Sources = append(first.Sources, SourceTrace{Root: "FAKE", Path: []string{"FAKE"}})
279	
280		// The untouched report of the same query is byte-identical to what T
281		// returned.
282		if got := mustMarshalTraceReport(t, second); !bytes.Equal(got, wantSecond) {
283			t.Errorf("second T report changed after editing the first:\n got %s\nwant %s", got, wantSecond)
284		}
285		if !reflect.DeepEqual(second.Sources, wantIndependenceTSources) {
286			t.Errorf("second T sources = %+v, want %+v", second.Sources, wantIndependenceTSources)
287		}
288		if second.Dataset != "T" || second.ContentID != snap.ContentID {
289			t.Errorf("second T metadata = %q %q, want %q %q", second.Dataset, second.ContentID, "T", snap.ContentID)
290		}
291	
292		// The report for the other downstream through the same M is independent as
293		// well.
294		if got := mustMarshalTraceReport(t, downU); !bytes.Equal(got, wantU) {
295			t.Errorf("U report changed after editing T's report:\n got %s\nwant %s", got, wantU)
296		}
297		if !reflect.DeepEqual(downU.Sources, wantIndependenceUSources) {
298			t.Errorf("U sources = %+v, want %+v", downU.Sources, wantIndependenceUSources)
299		}
300	
301		// The snapshot stays frozen.
302		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, snapshotBytes) {
303			t.Errorf("snapshot export changed:\n got %s\nwant %s", got, snapshotBytes)
304		}
305		if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, wantIndependenceSnapshotDatasets) {
306			t.Errorf("snapshot datasets changed:\n got %v\nwant %v", got, wantIndependenceSnapshotDatasets)
307		}
308	
309		// Fresh queries still describe the frozen snapshot, not the edited report.
310		freshT := traceReportOf(t, snap, "T")
311		if !reflect.DeepEqual(freshT.Sources, wantIndependenceTSources) {
312			t.Errorf("fresh T sources = %+v, want %+v", freshT.Sources, wantIndependenceTSources)
313		}
314		if freshT.ContentID != snap.ContentID || freshT.Dataset != "T" {
315			t.Errorf("fresh T metadata = %q %q, want %q %q", freshT.ContentID, freshT.Dataset, snap.ContentID, "T")
316		}
317		freshU := traceReportOf(t, snap, "U")
318		if !reflect.DeepEqual(freshU.Sources, wantIndependenceUSources) {
319			t.Errorf("fresh U sources = %+v, want %+v", freshU.Sources, wantIndependenceUSources)
320		}
321		if freshU.ContentID != snap.ContentID || freshU.Dataset != "U" {
322			t.Errorf("fresh U metadata = %q %q, want %q %q", freshU.ContentID, freshU.Dataset, snap.ContentID, "U")
323		}
324	}
325	
326	// TestTraceRootSingleElementPathIsIndependent pins the same guarantees for a
327	// root query: its one-element path [R1] and root field are independently owned,
328	// so editing them leaves the other held reports (another root query and a deep
329	// query), the snapshot export, and a fresh root query untouched.
330	func TestTraceRootSingleElementPathIsIndependent(t *testing.T) {
331		snap := snapshotOf(t, traceIndependenceGraphJSON)
332		root := traceReportOf(t, snap, "R1")
333		other := traceReportOf(t, snap, "R1")
334		deep := traceReportOf(t, snap, "T")
335		wantOther := mustMarshalTraceReport(t, other)
336		wantDeep := mustMarshalTraceReport(t, deep)
337		snapshotBytes := mustMarshalSnapshot(t, snap)
338	
339		if got := root.Sources; !reflect.DeepEqual(got, []SourceTrace{{Root: "R1", Path: []string{"R1"}}}) {
340			t.Fatalf("root sources = %+v, want single-element [R1]", got)
341		}
342	
343		root.Sources[0].Root = "HACK"
344		root.Sources[0].Path[0] = "HACK"
345		root.Sources[0].Path = append(root.Sources[0].Path, "EXTRA")
346	
347		if got := mustMarshalTraceReport(t, other); !bytes.Equal(got, wantOther) {
348			t.Errorf("other root report changed:\n got %s\nwant %s", got, wantOther)
349		}
350		if got := other.Sources; !reflect.DeepEqual(got, []SourceTrace{{Root: "R1", Path: []string{"R1"}}}) {
351			t.Errorf("other root sources = %+v, want untouched single-element [R1]", got)
352		}
353		if got := mustMarshalTraceReport(t, deep); !bytes.Equal(got, wantDeep) {
354			t.Errorf("deep T report changed after editing a root report:\n got %s\nwant %s", got, wantDeep)
355		}
356		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, snapshotBytes) {
357			t.Errorf("snapshot export changed:\n got %s\nwant %s", got, snapshotBytes)
358		}
359	
360		fresh := traceReportOf(t, snap, "R1")
361		if !reflect.DeepEqual(fresh.Sources, []SourceTrace{{Root: "R1", Path: []string{"R1"}}}) {
362			t.Errorf("fresh root sources = %+v, want [R1]", fresh.Sources)
363		}
364		if fresh.ContentID != snap.ContentID || fresh.Dataset != "R1" {
365			t.Errorf("fresh root metadata = %q %q, want %q %q", fresh.ContentID, fresh.Dataset, snap.ContentID, "R1")
366		}
367	}
368	
369	// TestTraceFailedQueriesAfterSuccessProduceNoReportAndChangeNothing pins the
370	// error boundary while a successful report is held open: an empty name keeps
371	// returning ErrInvalidArgument, an unknown name keeps returning ErrNotFound,
372	// neither returns a success report, and both leave the earlier report, its
373	// content identifier, and the input snapshot exactly as they were.
374	func TestTraceFailedQueriesAfterSuccessProduceNoReportAndChangeNothing(t *testing.T) {
375		snap := snapshotOf(t, traceIndependenceGraphJSON)
376		wantID := snap.ContentID
377		ok := traceReportOf(t, snap, "T")
378		wantReport := mustMarshalTraceReport(t, ok)
379		snapshotBytes := mustMarshalSnapshot(t, snap)
380		beforeDatasets := snapshotDatasetsCopy(snap)
381	
382		if report, err := TraceSources(snap, ""); report != nil || !errors.Is(err, ErrInvalidArgument) {
383			t.Errorf("empty query: report=%+v err=%v, want nil report and ErrInvalidArgument", report, err)
384		}
385		if report, err := TraceSources(snap, "ghost"); report != nil || !errors.Is(err, ErrNotFound) {
386			t.Errorf("unknown query: report=%+v err=%v, want nil report and ErrNotFound", report, err)
387		}
388	
389		if got := mustMarshalTraceReport(t, ok); !bytes.Equal(got, wantReport) {
390			t.Errorf("earlier report changed after failed queries:\n got %s\nwant %s", got, wantReport)
391		}
392		if !reflect.DeepEqual(ok.Sources, wantIndependenceTSources) {
393			t.Errorf("earlier sources = %+v, want %+v", ok.Sources, wantIndependenceTSources)
394		}
395		if snap.ContentID != wantID {
396			t.Errorf("snapshot content id changed: %q", snap.ContentID)
397		}
398		if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, beforeDatasets) {
399			t.Errorf("snapshot datasets changed after failed queries:\n got %v\nwant %v", got, beforeDatasets)
400		}
401		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, snapshotBytes) {
402			t.Errorf("snapshot export changed after failed queries:\n got %s\nwant %s", got, snapshotBytes)
403		}
404	
405		// A successful query still describes the frozen snapshot.
406		fresh := traceReportOf(t, snap, "T")
407		if !reflect.DeepEqual(fresh.Sources, wantIndependenceTSources) {
408			t.Errorf("fresh sources = %+v, want %+v", fresh.Sources, wantIndependenceTSources)
409		}
410	}
411	
412	// TestTraceSnapshotUnchangedBeforeAndAfterTracing compares the frozen document
413	// across successful and failed queries as a whole: the same content identifier,
414	// the same graph, and the same export bytes come out after tracing T, U, a
415	// root, and the rejected queries, and those bytes still parse as a legal
416	// snapshot whose id matches its graph.
417	func TestTraceSnapshotUnchangedBeforeAndAfterTracing(t *testing.T) {
418		snap := snapshotOf(t, traceIndependenceGraphJSON)
419		before := mustMarshalSnapshot(t, snap)
420	
421		for _, dataset := range []string{"T", "U", "R1", "R2", "M"} {
422			if report, err := TraceSources(snap, dataset); err != nil {
423				t.Fatalf("TraceSources(%q): %v", dataset, err)
424			} else {
425				// Display-edit the returned report, which must never write back.
426				report.Sources[0].Path[0] = "HACK"
427				report.Sources = append(report.Sources, SourceTrace{Root: "FAKE", Path: []string{"FAKE"}})
428			}
429		}
430		if _, err := TraceSources(snap, ""); !errors.Is(err, ErrInvalidArgument) {
431			t.Fatalf("empty query err = %v, want ErrInvalidArgument", err)
432		}
433		if _, err := TraceSources(snap, "ghost"); !errors.Is(err, ErrNotFound) {
434			t.Fatalf("unknown query err = %v, want ErrNotFound", err)
435		}
436	
437		after := mustMarshalSnapshot(t, snap)
438		if !bytes.Equal(after, before) {
439			t.Errorf("snapshot export differs after tracing:\n got %s\nwant %s", after, before)
440		}
441		parsed, err := ParseSnapshot(after)
442		if err != nil {
443			t.Fatalf("snapshot no longer parses after tracing: %v", err)
444		}
445		if parsed.ContentID != snap.ContentID {
446			t.Errorf("parsed id = %q, want %q", parsed.ContentID, snap.ContentID)
447		}
448		if !reflect.DeepEqual(parsed.Graph, snap.Graph) {
449			t.Errorf("parsed graph differs:\n got %#v\nwant %#v", parsed.Graph, snap.Graph)
450		}
451		if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, wantIndependenceSnapshotDatasets) {
452			t.Errorf("snapshot datasets = %v, want %v", got, wantIndependenceSnapshotDatasets)
453		}
454	}
455	
456	// TestTraceIndependentReportStillObeysBusinessRulesWithUnicodeNames verifies on
457	// the independence results themselves that the existing business rules still
458	// hold and that name spellings survive verbatim: Chinese characters, ASCII
459	// case, and surrounding spaces are all kept; each root appears once; the
460	// shortest route wins; equal-length ties are decided element by element from
461	// the query end by UTF-8 byte order; sources are ordered by root name. Editing
462	// the returned names and re-querying returns the original frozen answer.
463	func TestTraceIndependentReportStillObeysBusinessRulesWithUnicodeNames(t *testing.T) {
464		// Q reaches root r in two equal-length relations — via A or via a — and
465		// reaches the two spaced/Chinese roots through the spaced intermediate
466		// " 中间 ". "A" (0x41) beats "a" (0x61) at the first differing position.
467		graphJSON := `{"datasets":[
468			{"name":"Q","upstreams":["A","a"," 中间 "]},
469			{"name":"A","upstreams":["r"]},
470			{"name":"a","upstreams":["r"]},
471			{"name":"r","upstreams":[]},
472			{"name":" 中间 ","upstreams":[" 根 ","根"]},
473			{"name":" 根 ","upstreams":[]},
474			{"name":"根","upstreams":[]}
475		]}`
476		snap := snapshotOf(t, graphJSON)
477	
478		// Roots sort by UTF-8 byte order: the space-prefixed name (0x20) first,
479		// then "r" (0x72), then the Chinese root (0xE6...).
480		want := []SourceTrace{
481			{Root: " 根 ", Path: []string{"Q", " 中间 ", " 根 "}},
482			{Root: "r", Path: []string{"Q", "A", "r"}},
483			{Root: "根", Path: []string{"Q", " 中间 ", "根"}},
484		}
485		report := traceReportOf(t, snap, "Q")
486		if !reflect.DeepEqual(report.Sources, want) {
487			t.Fatalf("Sources = %+v\nwant %+v", report.Sources, want)
488		}
489		if report.ContentID != snap.ContentID || report.Dataset != "Q" {
490			t.Errorf("metadata = %q %q, want %q %q", report.ContentID, report.Dataset, snap.ContentID, "Q")
491		}
492	
493		// Each root appears exactly once.
494		seen := map[string]int{}
495		for _, src := range report.Sources {
496			seen[src.Root]++
497		}
498		for root, count := range seen {
499			if count != 1 {
500				t.Errorf("root %q reported %d times, want exactly once", root, count)
501			}
502		}
503	
504		// The spaced intermediate query keeps every spelling verbatim, and the
505		// spaced root's own query is a single-element path with its spaces intact.
506		mid := traceReportOf(t, snap, " 中间 ")
507		wantMid := []SourceTrace{
508			{Root: " 根 ", Path: []string{" 中间 ", " 根 "}},
509			{Root: "根", Path: []string{" 中间 ", "根"}},
510		}
511		if !reflect.DeepEqual(mid.Sources, wantMid) {
512			t.Errorf("intermediate sources = %+v, want %+v", mid.Sources, wantMid)
513		}
514		spacedRoot := traceReportOf(t, snap, " 根 ")
515		if got := spacedRoot.Sources; !reflect.DeepEqual(got, []SourceTrace{{Root: " 根 ", Path: []string{" 根 "}}}) {
516			t.Errorf("spaced root sources = %+v, want single-element verbatim path", got)
517		}
518	
519		// Edit every name position of every returned path, then re-query: the
520		// frozen answer must come back byte-for-byte, proving the independence copy
521		// preserved the exact spellings.
522		for i := range report.Sources {
523			for j := range report.Sources[i].Path {
524				report.Sources[i].Path[j] = " 改 A "
525			}
526			report.Sources[i].Root = " 改 A "
527			report.Sources[i].Path = append(report.Sources[i].Path, "追加")
528		}
529		for i := range mid.Sources {
530			mid.Sources[i].Path[0] = "HACK"
531		}
532	
533		fresh := traceReportOf(t, snap, "Q")
534		if !reflect.DeepEqual(fresh.Sources, want) {
535			t.Errorf("fresh sources after edits = %+v, want %+v", fresh.Sources, want)
536		}
537		if fresh.Dataset != "Q" || fresh.ContentID != snap.ContentID {
538			t.Errorf("fresh metadata = %q %q, want %q %q", fresh.Dataset, fresh.ContentID, "Q", snap.ContentID)
539		}
540		freshMid := traceReportOf(t, snap, " 中间 ")
541		if !reflect.DeepEqual(freshMid.Sources, wantMid) {
542			t.Errorf("fresh intermediate sources = %+v, want %+v", freshMid.Sources, wantMid)
543		}
544	}
