141	// TestTraceDeepConvergingBranches fixes the tie-break when two branches pass
142	// through different intermediate datasets and merge before the root. From T
143	// to R both routes have four relations:
144	//
145	//	T -> A -> Z -> M -> R
146	//	T -> B -> C -> M -> R
147	//
148	// There is no shorter route. The choice is made at the first differing name,
149	// which is position 1: A < B, so the path through A and Z wins even though
150	// the other branch passes through C, which is bytewise smaller than Z.
151	func TestTraceDeepConvergingBranches(t *testing.T) {
152		report := traceOf(t, `{"datasets":[
153			{"name":"T","upstreams":["B","A"]},
154			{"name":"A","upstreams":["Z"]},
155			{"name":"Z","upstreams":["M"]},
156			{"name":"B","upstreams":["C"]},
157			{"name":"C","upstreams":["M"]},
158			{"name":"M","upstreams":["R"]},
159			{"name":"R","upstreams":[]}
160		]}`, "T")
161		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "Z", "M", "R"}}}
162		if !reflect.DeepEqual(report.Sources, want) {
163			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
164		}
165	}
