190	// TestTraceShortPathBeatsSmallerNamedLongRoute fixes that the number of
191	// direct relations is decided first: the same root may also be reachable
192	// through a branch whose names are all bytewise smaller, but when that branch
193	// is one relation longer, the shorter path still represents the root.
194	func TestTraceShortPathBeatsSmallerNamedLongRoute(t *testing.T) {
195		// Short route (3 relations): T -> A -> Z -> R.
196		// Long route (4 relations): T -> 0a -> 0b -> 0c -> R; every name on it
197		// sorts below "A" because '0' (0x30) precedes 'A' (0x41) in UTF-8 bytes.
198		report := traceOf(t, `{"datasets":[
199			{"name":"T","upstreams":["0a","A"]},
200			{"name":"A","upstreams":["Z"]},
201			{"name":"Z","upstreams":["R"]},
202			{"name":"0a","upstreams":["0b"]},
203			{"name":"0b","upstreams":["0c"]},
204			{"name":"0c","upstreams":["R"]},
205			{"name":"R","upstreams":[]}
206		]}`, "T")
207		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "Z", "R"}}}
208		if !reflect.DeepEqual(report.Sources, want) {
209			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
210		}
211	}
